class Solution {
    public int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        counts.put(0, 1);
        int cur = 0, ans = 0;
        for (int n : nums) {
            cur += n;
            if (counts.containsKey(cur - k)) {
                ans += counts.get(cur - k);
            }
            counts.put(cur, counts.getOrDefault(cur, 0) + 1);
        }
        return ans;
    }
}

