class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> res = new ArrayList<>();
        if (p.length() > s.length()) return res;
        int[] pv = new int[26], sv = new int[26];
        for (char c : p.toCharArray()) pv[c - 'a']++;
        for (int i = 0; i < s.length(); ++i) {
            sv[s.charAt(i) - 'a']++;
            if (i >= p.length()) sv[s.charAt(i - p.length()) - 'a']--;
            if (Arrays.equals(pv, sv)) res.add(i - p.length() + 1);
        }
        return res;
    }
}

