int maxPathSum(TreeNode* root) {
    int ans = -1e9;
    auto dfs = [&](auto self, TreeNode* node) -> int {
        if (!node) return 0;
        int l = max(0, self(self, node->left));
        int r = max(0, self(self, node->right));
        ans = max(ans, node->val + l + r);
        return node->val + max(l, r);
    };
    dfs(dfs, root);
    return ans;
}

